fun thm stx =>
  have __discr := stx;
  if __discr.isOfKind `Lean.Parser.Attr.simple = true then
    have __discr_1 := __discr.getArg 0;
    if __discr_1.matchesIdent `algebraize = true then
      have __discr_2 := __discr.getArg 1;
      if __discr_2.matchesNull 1 = true then
        have __discr := __discr_2.getArg 0;
        bif false || __discr.isOfKind `ident then
          have name := { raw := __discr };
          pure name.getId
        else
          have __discr := __discr_2.getArg 0;
          Lean.throwError (Lean.toMessageData "unexpected algebraize argument")
      else
        have __discr_3 := __discr.getArg 1;
        if __discr_3.matchesNull 0 = true then
          match thm with
          | `RingHom.str t => pure (`Algebra.str t)
          | x =>
            Lean.throwError
              (Lean.toMessageData
                "theorem name must be of the form `RingHom.Property` if no argument is provided")
        else
          have __discr := __discr.getArg 1;
          Lean.throwError (Lean.toMessageData "unexpected algebraize argument")
    else
      have __discr_2 := __discr.getArg 0;
      have __discr := __discr.getArg 1;
      Lean.throwError (Lean.toMessageData "unexpected algebraize argument")
